contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 hash, uint amount) public payable {
        require(address(this).balance >= amount);
        bool settleReverted;
        try c.settle() { settleReverted = false; } catch { settleReverted = true; }
        bool lockReverted;
        if (amount == 1 ether) {
            try c.lockInGuess{value: amount}(hash) { lockReverted = false; } catch { lockReverted = true; }
        } else {
            try c.lockInGuess{value: amount}(hash) { lockReverted = false; } catch { lockReverted = true; }
        }
        assert(settleReverted && lockReverted == (amount != 1 ether));
    }
    receive() external payable {}
}

