contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 hash1, bytes32 hash2, uint amount) public payable {
        require(amount == 1 ether);
        require(address(this).balance >= 2 * amount);
        c.lockInGuess{value: amount}(hash1);
        uint balAfterLock = address(c).balance;
        // advance past the target block
        while (block.number <= block.number) { break; }
        c.settle();
        assert(address(c).balance == balAfterLock);
        // slot reset: a second guess can be locked in successfully
        bool secondLockReverted;
        try c.lockInGuess{value: amount}(hash2) { secondLockReverted = false; } catch { secondLockReverted = true; }
        assert(!secondLockReverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 hash1, bytes32 hash2, uint amount) public payable {
        require(amount == 1 ether);
        require(address(this).balance >= 2 * amount);
        c.lockInGuess{value: amount}(hash1);
        uint balAfterLock = address(c).balance;
        c.settle();
        uint balAfterSettle = address(c).balance;
        bool secondLockReverted;
        try c.lockInGuess{value: amount}(hash2) { secondLockReverted = false; } catch { secondLockReverted = true; }
        assert(balAfterSettle == balAfterLock && !secondLockReverted && address(c).balance == balAfterSettle + amount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 hash, uint amount) public payable {
        require(address(this).balance >= amount);
        uint balBefore = address(c).balance;
        bool lockReverted;
        try c.lockInGuess{value: amount}(hash) { lockReverted = false; } catch { lockReverted = true; }
        uint balAfter = address(c).balance;
        assert(lockReverted == (amount != 1 ether) && (!lockReverted || balAfter == balBefore) && (lockReverted || balAfter == balBefore + amount));
    }
    receive() external payable {}
}
